      const pitchRateFf = clamp((pitchDesN - pitchDes) / dtF, -6, 6);

      // Desired total thrust force
      let fSumDes = fy / Math.max(0.5, Math.cos(st.att.roll) * Math.cos(st.att.pitch));
      if (t > 6.95 && obs.gateIndex === 3 && st.pos.y <= 0.08 && Math.hypot(st.pos.x - PAD.x, st.pos.z - PAD.z) < 0.12 && Math.hypot(st.vel.x, st.vel.y, st.vel.z) < 0.25) {
        return { thrust: 0, roll: 0, pitch: 0, yawRate: 0 };
      }

