      }

      const st = shadow || {
        t: obs.t, pos: obs.pos, vel: obs.vel, att: obs.att, rates: obs.rates,
        motors: [1.8, 1.8, 1.8, 1.8], integral: { roll: 0, pitch: 0 },
      };

      const t = st.t;
      sampleSpline(segs, t, ref);
      const kp = 14.0, kd = 7.0;
      const kpy = 18.0, kdy = 8.5;

      const ex = ref.pos.x - st.pos.x, vx = ref.vel.x - st.vel.x;
      const ey = ref.pos.y - st.pos.y, vy = ref.vel.y - st.vel.y;
      const ez = ref.pos.z - st.pos.z, vz = ref.vel.z - st.vel.z;

      const ax = ref.acc.x + kp * ex + kd * vx;
      const ay = ref.acc.y + kpy * ey + kdy * vy;
      const az = ref.acc.z + kp * ez + kd * vz;

      previewWind(t, params, wind);
      const m = params.mass;
      const fx = m * ax - 0.42 * (wind.x - st.vel.x);
      const fy = Math.max(0.5, m * (ay + 9.81) + 0.42 * st.vel.y);
      const fz = m * az - 0.42 * (wind.z - st.vel.z);

      const dtF = 0.01;
      sampleSpline(segs, t + dtF, refNext);
      previewWind(t + dtF, params, windNext);
      const fxN = m * (refNext.acc.x + kp * ex + kd * vx) - 0.42 * (windNext.x - st.vel.x);
      const fyN = Math.max(0.5, m * (refNext.acc.y + 9.81 + kpy * ey + kdy * vy) + 0.42 * st.vel.y);
      const fzN = m * (refNext.acc.z + kp * ez + kd * vz) - 0.42 * (windNext.z - st.vel.z);

