  const warmFallback = makeInstance(10);
  const obsUnmatched = {
    t: 0,
    pos: { x: -2.104, y: 0.0701, z: -1.652 },
    vel: { x: 0, y: 0, z: 0 },
    att: { roll: 0, pitch: 0, yaw: 0 },
    rates: { roll: 0, pitch: 0, yaw: 0 },
    gateIndex: 0,
  };
  for (let i = 0; i < 40; i++) {
    obsUnmatched.t = +(i * 0.01).toFixed(4);
    warmFallback.step(obsUnmatched);
  }
  return makeInstance(250000);
}

